def rewrite(language):
    path = BUNDLE / ("index.md" if language == "ja" else f"index.{language}.md")
    text = path.read_text(encoding="utf-8-sig")
    match = re.match(r"---\n(.*?)\n---\n", text, re.S)
    if not match:
        raise ValueError(f"Missing front matter: {path}")
    front = match.group(1)
    front = re.sub(r"(?m)^date:.*\n", "", front)
    title, description, body = PAGES[language]
    front = re.sub(r"(?m)^title:.*$", "title: " + json.dumps(title, ensure_ascii=False), front, count=1)
    front = re.sub(r"(?m)^description:.*$", "description: " + json.dumps(description, ensure_ascii=False), front, count=1)
    front += f"\ndate: 2023-04-17T00:26:55+09:00\nlastmod: {TODAY}T00:00:00+09:00"
    path.write_text("---\n" + front + "\n---\n\n" + body + "\n", encoding="utf-8")

for lang in LANGS:
    rewrite(lang)
print("Refreshed HTML5 UP guide in thirteen editions")
